cypress_script:
describe('File Upload and Download Tests', () => {
  it('should upload a file successfully', () => {
    cy.visit('https://demoqa.com/upload-download');
    const filePath = 'path/to/your/file.txt'; // Use an appropriate test file path
    cy.get('#uploadFile').attachFile(filePath);
    // Assert that the file is uploaded by checking if the input is visible
    cy.get('#uploadFile').should('be.visible');
  });

  it('should download the sample image', () => {
    cy.visit('https://demoqa.com/upload-download');
    cy.get('#downloadButton').should('be.visible').click();
    // Check that the URL remains the same after the download
    cy.url().should('eq', 'https://demoqa.com/upload-download');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('File Upload and Download Tests', () => {
  test('should upload a file successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    const filePath = 'path/to/your/file.txt'; // Use an appropriate test file path
    await page.setInputFiles('#uploadFile', filePath);
    // Assert that the file input is visible
    const uploadInput = await page.locator('#uploadFile');
    await expect(uploadInput).toBeVisible();
  });

  test('should download the sample image', async ({ page }) => {
    await page.goto('https://demoqa.com/upload-download');
    await page.click('#downloadButton');
    // Check that the URL remains the same after the download
    await expect(page).toHaveURL('https://demoqa.com/upload-download');
  });
});
